def render(q):
    if q[0] == "mc":
        _, text, opts, right, why = q
        lines = [f"**Multiple choice.** {text}"] + [f"- {o}{' ✓' if i == right else ''}" for i, o in enumerate(opts)]
    else:
        _, text, ans, why = q
        lines = [f"**Fill in the blank.** {text} [answer: {ans}]"]
    if why:
        lines.append(f"> {why}")
    return "\n".join(lines)

for slug, works in Q.items():
    f = pathlib.Path(f"paths/{slug}.md"); L = f.read_text(encoding="utf-8").split("\n")
    added = 0
    for wid, qs in works.items():
        start = next(i for i, l in enumerate(L) if re.match(rf"- id: {wid} ·", l))
        quiz = next(i for i in range(start, len(L)) if L[i].strip() == "### Quiz")
        end = next((i for i in range(quiz + 1, len(L)) if re.match(r"(#{1,3} |---\s*$)", L[i])), len(L))
        block = "\n".join(L[quiz:end])
        new = [render(q) for q in qs if q[1] not in block]
        if not new: continue
        while end > quiz and L[end - 1].strip() == "": end -= 1
        L[end:end] = [""] + "\n\n".join(new).split("\n")
        added += len(new)
    f.write_text("\n".join(L), encoding="utf-8", newline="\n")
    print(slug, "added", added)
